				  	if (seg1Val = "1P")
				  	{
					  	set elObj.Payer = $PIECE(segVal, x12Doc.ElementSeparator , 4)
				  	}
				  	if (seg1Val = "IL")
				  	{
					  	set elObjSub.Subscriber = $PIECE(segVal, x12Doc.ElementSeparator , 5) _ " " _ $PIECE(segVal, x12Doc.ElementSeparator , 4)
					  	set elObjSub.SubscriberId = $PIECE(segVal, x12Doc.ElementSeparator , 10)
				  	}
				  	if (seg1Val = "03")
